function validateManifest(manifest) {
  if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest)) throw Error('manifest must be an object');
  if (manifest.version !== 1) throw Error('manifest version must be 1');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) throw Error('manifest entry must be an object');
    validatePath(entry.path);
    if (seen.has(entry.path)) throw Error('duplicate manifest entry');
    seen.add(entry.path);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) throw Error('invalid manifest sha256');
    if (typeof entry.size !== 'number' || !Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('invalid manifest size');
    if (typeof entry.mode !== 'number' || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 0o777) throw Error('invalid manifest mode');
  }
}
export function verifyManifest(root, manifest) {
  validateRoot(root);
  validateManifest(manifest);
  const unchanged = [], changed = [], missing = [], unsafe = [];
  for (const entry of manifest.files) {
    const current = inspect(root, entry.path);
    if (current.kind === 'missing') { missing.push(entry.path); continue; }
    if (current.kind === 'unsafe') { unsafe.push(entry.path); continue; }
    const reasons = [];
    if (current.sha256 !== entry.sha256 || current.size !== entry.size) reasons.push('content');
    if (current.mode !== entry.mode) reasons.push('mode');
    if (reasons.length) changed.push({path: entry.path, reasons});
    else unchanged.push(entry.path);
  }
  const byPath = (a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
  unchanged.sort(); missing.sort(); unsafe.sort(); changed.sort(byPath);
  return {ok: changed.length === 0 && missing.length === 0 && unsafe.length === 0, unchanged, changed, missing, unsafe};
}

function main(argv) {
  const [command, root, ...rest] = argv;
  if (command === 'create') {
    if (root === undefined) throw Error('usage: snapshot.js create ROOT [PATH ...]');
    return {text: JSON.stringify(createManifest(root, rest)), code: 0};
  }
  if (command === 'verify') {
    if (root === undefined || rest.length !== 1) throw Error('usage: snapshot.js verify ROOT MANIFEST_FILE');
    const text = fs.readFileSync(rest[0], 'utf8');
    let manifest;
    try { manifest = JSON.parse(text); }
    catch { throw Error('manifest file is not valid JSON'); }
    const report = verifyManifest(root, manifest);
    return {text: JSON.stringify(report), code: report.ok ? 0 : 1};
  }
  throw Error('usage: snapshot.js create|verify ...');
}

if (process.argv[1] && import.meta.url === url.pathToFileURL(process.argv[1]).href) {
