import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFileSync, spawnSync} from 'node:child_process';
import * as snapshot from '../snapshot.js';

const CLI = path.join(import.meta.dirname, '..', 'snapshot.js');

function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  fs.mkdirSync(path.join(dir, 'sub'));
  fs.writeFileSync(path.join(dir, 'sub', 'b.txt'), 'hello');
  fs.chmodSync(path.join(dir, 'sub', 'b.txt'), 0o644);
  fs.writeFileSync(path.join(dir, 'a b\tc.txt'), 'sp ace');
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  return dir;
}

test('createManifest sorts by JS string order and accepts empty selection', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root, ['sub/b.txt', 'a b\tc.txt']);
  assert.deepEqual(manifest.files.map(f => f.path), ['a b\tc.txt', 'sub/b.txt']);
  assert.deepEqual(snapshot.createManifest(root, []), {version: 1, files: []});
});

test('inputs are not mutated', t => {
  const root = fixture(t);
  const paths = ['sub/b.txt', 'a b\tc.txt'];
  snapshot.createManifest(root, paths);
  assert.deepEqual(paths, ['sub/b.txt', 'a b\tc.txt']);
  const manifest = snapshot.createManifest(root, ['sub/b.txt', 'a b\tc.txt']);
  const copy = JSON.parse(JSON.stringify(manifest));
  snapshot.verifyManifest(root, manifest);
  assert.deepEqual(manifest, copy);
});

test('mode-only and combined drift reasons', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root, ['sub/b.txt']);
  fs.chmodSync(path.join(root, 'sub', 'b.txt'), 0o600);
  assert.deepEqual(snapshot.verifyManifest(root, manifest).changed, [{path: 'sub/b.txt', reasons: ['mode']}]);
  fs.writeFileSync(path.join(root, 'sub', 'b.txt'), 'hellO');
  fs.chmodSync(path.join(root, 'sub', 'b.txt'), 0o600);
  const report = snapshot.verifyManifest(root, manifest);
  assert.deepEqual(report.changed, [{path: 'sub/b.txt', reasons: ['content', 'mode']}]);
  assert.equal(report.ok, false);
});

test('symlinks are unsafe, never followed', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root, ['sub/b.txt']);
  fs.rmSync(path.join(root, 'sub'), {recursive: true});
  fs.symlinkSync(path.join(root, 'real'), path.join(root, 'sub'));
  fs.mkdirSync(path.join(root, 'real'));
  fs.writeFileSync(path.join(root, 'real', 'b.txt'), 'hello');
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unsafe, ['sub/b.txt']);
  assert.throws(() => snapshot.createManifest(root, ['sub/b.txt']));
});

test('final component that is a directory is unsafe', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root, ['sub/b.txt']);
  fs.rmSync(path.join(root, 'sub', 'b.txt'));
  fs.mkdirSync(path.join(root, 'sub', 'b.txt'));
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unsafe, ['sub/b.txt']);
});

test('unsorted manifests verify and report sorted', t => {
  const root = fixture(t);
  const manifest = {version: 1, files: [...snapshot.createManifest(root, ['sub/b.txt', 'a b\tc.txt']).files].reverse()};
  assert.deepEqual(snapshot.verifyManifest(root, manifest).unchanged, ['a b\tc.txt', 'sub/b.txt']);
});

test('unknown entry fields are ignored', t => {
  const root = fixture(t);
  const manifest = snapshot.createManifest(root, ['sub/b.txt']);
  manifest.files[0].extra = 'x';
  manifest.note = 'y';
  assert.equal(snapshot.verifyManifest(root, manifest).ok, true);
});

test('invalid manifests throw rather than reporting drift', t => {
  const root = fixture(t);
  const good = snapshot.createManifest(root, ['sub/b.txt']).files[0];
  const bad = [
    null, [], 'x', {version: 1}, {version: '1', files: []}, {version: 1, files: {}},
    {version: 1, files: [null]}, {version: 1, files: [[good]]},
    {version: 1, files: [{...good, sha256: good.sha256.toUpperCase()}]},
    {version: 1, files: [{...good, sha256: 'abc'}]},
    {version: 1, files: [{...good, size: -1}]},
    {version: 1, files: [{...good, size: 1.5}]},
    {version: 1, files: [{...good, mode: 512}]},
    {version: 1, files: [{...good, mode: -1}]},
    {version: 1, files: [{...good, path: '/abs'}]},
    {version: 1, files: [{...good, path: 'a/../b'}]},
    {version: 1, files: [good, {...good}]},
  ];
  for (const manifest of bad) assert.throws(() => snapshot.verifyManifest(root, manifest), `${JSON.stringify(manifest)}`);
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'nope'), {version: 1, files: []}));
});

test('CLI create prints one JSON line and exits 0', t => {
  const root = fixture(t);
  const result = spawnSync(process.execPath, [CLI, 'create', root, 'sub/b.txt'], {encoding: 'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, JSON.stringify(snapshot.createManifest(root, ['sub/b.txt'])) + '\n');
});

test('CLI verify exits 0 clean, 1 on drift, 2 on errors', t => {
  const root = fixture(t);
  const file = path.join(root, '..', path.basename(root) + '.json');
  t.after(() => fs.rmSync(file, {force: true}));
  fs.writeFileSync(file, execFileSync(process.execPath, [CLI, 'create', root, 'sub/b.txt'], {encoding: 'utf8'}));

  let result = spawnSync(process.execPath, [CLI, 'verify', root, file], {encoding: 'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.deepEqual(JSON.parse(result.stdout), {ok: true, unchanged: ['sub/b.txt'], changed: [], missing: [], unsafe: []});

  fs.writeFileSync(path.join(root, 'sub', 'b.txt'), 'drift');
  result = spawnSync(process.execPath, [CLI, 'verify', root, file], {encoding: 'utf8'});
  assert.equal(result.status, 1);
  assert.equal(result.stderr, '');
  assert.equal(JSON.parse(result.stdout).ok, false);

  for (const args of [[], ['bogus'], ['create'], ['verify', root], ['verify', root, file, 'x'],
    ['verify', root, path.join(root, 'nofile.json')], ['create', root, '../x']]) {
    const bad = spawnSync(process.execPath, [CLI, ...args], {encoding: 'utf8'});
    assert.equal(bad.status, 2, `args: ${args}`);
    assert.equal(bad.stdout, '');
    assert.match(bad.stderr, /\S/);
  }

  fs.writeFileSync(file, '{not json');
  const badJson = spawnSync(process.execPath, [CLI, 'verify', root, file], {encoding: 'utf8'});
  assert.equal(badJson.status, 2);
  assert.equal(badJson.stdout, '');
});

test('importing the module does not run the CLI', () => {
  const result = spawnSync(process.execPath, ['-e', `import(${JSON.stringify(CLI)}).then(() => {})`], {encoding: 'utf8'});
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

